package app.veyra;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import java.io.*;import java.util.concurrent.*;
public final class UpdatesActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status,releaseNotes;private Button action;private ProgressBar progress;private AppUpdates.Release release;private File ready;private boolean busy;
 public void onCreate(Bundle saved){super.onCreate(saved);Ui.configure(this);LinearLayout root=Ui.column(this);Button back=Ui.quiet(this,"‹  Back");back.setOnClickListener(v->finish());root.addView(back);root.addView(Ui.text(this,"Stay up to date",30,Ui.INK));root.addView(Ui.text(this,"Get new Velixio versions here. Android will ask you to confirm installation.",14,Ui.MUTED));try{root.addView(Ui.text(this,"Installed · "+getPackageManager().getPackageInfo(getPackageName(),0).versionName,13,Ui.ACCENT));}catch(Exception ignored){}
 LinearLayout card=Ui.card(this);status=Ui.text(this,"Checking GitHub releases…",17,Ui.INK);status.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);card.addView(status);releaseNotes=Ui.text(this,"",14,Ui.MUTED);card.addView(releaseNotes);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(Ui.ACCENT));card.addView(progress);action=Ui.primary(this,"Check for updates");action.setOnClickListener(v->{if(busy)return;if(ready!=null)install();else if(release!=null)download();else check();});card.addView(action);root.addView(card);
 Switch automatic=new Switch(this);automatic.setText("Check automatically");automatic.setTextColor(Ui.INK);automatic.setMinimumHeight(Ui.dp(this,56));automatic.setChecked(getSharedPreferences("update-settings",0).getBoolean("automatic",true));automatic.setOnCheckedChangeListener((v,on)->getSharedPreferences("update-settings",0).edit().putBoolean("automatic",on).apply());root.addView(automatic);root.addView(Ui.text(this,"Updates are checked over HTTPS. Downloads must match GitHub’s checksum, this app’s signing identity and a newer version before installation.",13,Ui.MUTED));Button website=Ui.quiet(this,"Open release history ↗");website.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/unidentified24/Velixio/releases"))));root.addView(website);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(root);setContentView(scroll);Ui.insets(this,scroll,20);check();}
 private void state(String message,boolean working){status.setText(message);busy=working;action.setEnabled(!working);progress.setVisibility(working?android.view.View.VISIBLE:android.view.View.GONE);progress.setIndeterminate(working);}
 private void check(){state("Checking GitHub releases…",true);worker.execute(()->{try{AppUpdates.Release found=AppUpdates.check(this);runOnUiThread(()->{if(isDestroyed())return;release=found;releaseNotes.setText(found==null?"":StorageTools.format(found.size)+" · "+found.version+"\n\n"+found.notes);state(found==null?"No newer compatible APK was found. Releases need a version number and an attached APK with a checksum.":found.version+" is available",false);action.setText(found==null?"Check again":"Download update");});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()){state("Couldn’t reach the releases. Check your connection and try again.",false);action.setText("Try again");}});}});}
 private void download(){state("Downloading update…",true);worker.execute(()->{try{File file=AppUpdates.download(this,release,(bytes,total)->runOnUiThread(()->{if(isDestroyed())return;status.setText(total>0?"Downloading · "+Math.min(100,bytes*100/total)+"%":"Downloading update…");if(total>0){progress.setIndeterminate(false);progress.setProgress((int)Math.min(100,bytes*100/total));}}));runOnUiThread(()->{if(isDestroyed()){file.delete();return;}ready=file;state("Verified and ready to install",false);action.setText("Install update");});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()){state(e instanceof SecurityException?"This download failed the update safety checks. It has been removed.":"Download interrupted. Please try again.",false);action.setText("Retry download");}});}});}
 private void install(){try{if(Build.VERSION.SDK_INT>=26&&!getPackageManager().canRequestPackageInstalls()){status.setText("Allow updates from Velixio in Android settings, then return and tap Install update.");startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));return;}AppUpdates.verify(this,ready);Uri uri=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".updates",ready);startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){state("Android could not open this update. Please download it again or use release history.",false);if(ready!=null)ready.delete();ready=null;action.setText("Download again");}}
 protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
